import Foundation

/// The Mind Score network, ported from `src/signals/net.js`.
///
/// Four signals in, one number out. Each input is the wearer's reading for that
/// signal expressed as a z-score against their own fourteen-day baseline, so
/// zero is an ordinary day for that person and the same input means the same
/// thing for everybody.
///
/// Architecture 4-16-10-1, tanh between layers and a logistic at the end: 261
/// weights. The weights are not written by hand and are not fitted to any
/// person. They are generated by `tools/net/train.py`, which fits them against
/// the published-coefficient reference model stated in `Reference` below and
/// measures the error; `ios/tools/gen-weights.mjs` copies them out of the
/// JavaScript the web app loads, so the two products run the same numbers.
///
/// Why a network and not the dot product it looks like: movement does not add
/// to the score, it gates the other three. A reading taken during a run has to
/// discount heart and sweat rather than count them as stress, and that is a
/// product of two terms, which no weighted sum can express.
public struct MindScoreNetwork: Sendable {

    public struct Layer: Sendable {
        public let rows: Int
        public let cols: Int
        /// Row major: the weight from input `i` to output `j` is `w[i * cols + j]`.
        public let w: [Double]
        public let b: [Double]
        public let isLast: Bool
    }

    /// What one run produced, including every activation on the way, because a
    /// figure that draws the network needs them rather than an illustration.
    public struct Run: Sendable {
        public let score: Int
        public let p: Double
        public let activations: [[Double]]
        /// The inputs after clamping, which is what the network actually saw.
        public let clampedInput: [Double]
    }

    public enum LoadError: Error, CustomStringConvertible {
        case resourceMissing(String)
        case malformed(String)

        public var description: String {
            switch self {
            case .resourceMissing(let name):
                return "The weights file \(name) is not in the app bundle. Add it to the target's Copy Bundle Resources step."
            case .malformed(let why):
                return "The weights file is not usable: \(why)"
            }
        }
    }

    public let architecture: [Int]
    public let zLimit: Double
    public let layers: [Layer]

    /// The order the four inputs are read in. Matches `SIGNALS` in net.js.
    public static let inputOrder: [Signal] = [.heart, .sweat, .temp, .move]

    /// Total weights and biases. 261 for the shipped file.
    public var parameterCount: Int {
        layers.reduce(0) { $0 + $1.w.count + $1.b.count }
    }

    // MARK: Loading

    private struct File: Decodable {
        struct Layer: Decodable {
            let w: [Double]
            let b: [Double]
        }
        let arch: [Int]
        let zLimit: Double
        let layers: [Layer]
    }

    public init(jsonData: Data) throws {
        let file: File
        do {
            file = try JSONDecoder().decode(File.self, from: jsonData)
        } catch {
            throw LoadError.malformed("could not be decoded (\(error))")
        }
        guard file.arch.count >= 2 else {
            throw LoadError.malformed("architecture needs at least two layers")
        }
        guard file.arch.count - 1 == file.layers.count else {
            throw LoadError.malformed("architecture lists \(file.arch.count) layers but \(file.layers.count) weight blocks were given")
        }
        guard file.zLimit > 0 else {
            throw LoadError.malformed("zLimit must be positive")
        }
        var built: [Layer] = []
        for (i, l) in file.layers.enumerated() {
            let rows = file.arch[i]
            let cols = file.arch[i + 1]
            guard l.w.count == rows * cols else {
                throw LoadError.malformed("layer \(i) needs \(rows * cols) weights, got \(l.w.count)")
            }
            guard l.b.count == cols else {
                throw LoadError.malformed("layer \(i) needs \(cols) biases, got \(l.b.count)")
            }
            guard l.w.allSatisfy({ $0.isFinite }), l.b.allSatisfy({ $0.isFinite }) else {
                throw LoadError.malformed("layer \(i) holds a value that is not a finite number")
            }
            built.append(Layer(rows: rows, cols: cols, w: l.w, b: l.b,
                               isLast: i == file.layers.count - 1))
        }
        self.architecture = file.arch
        self.zLimit = file.zLimit
        self.layers = built
    }

    /// The name of the bundled weights file, without its extension.
    public static let resourceName = "net-weights"

    /// Loads the weights from a bundle. Looked up at the bundle root and then
    /// under `Resources/`, because the two build routes place it differently:
    /// Swift Package Manager puts it in a generated resource bundle, an Xcode
    /// app target puts it wherever the Copy Bundle Resources step says.
    public static func load(from bundle: Bundle) throws -> MindScoreNetwork {
        let url = bundle.url(forResource: resourceName, withExtension: "json")
            ?? bundle.url(forResource: resourceName, withExtension: "json", subdirectory: "Resources")
        guard let url else { throw LoadError.resourceMissing("\(resourceName).json") }
        return try MindScoreNetwork(jsonData: try Data(contentsOf: url))
    }

    /// The bundle the weights ship in for whichever build route compiled this
    /// file.
    public static var resourceBundle: Bundle {
        #if SWIFT_PACKAGE
        return Bundle.module
        #else
        return Bundle.main
        #endif
    }

    /// The shipped network. Throws rather than crashing, so a missing resource
    /// shows as a screen that says what is wrong instead of a launch crash.
    public static func bundled() throws -> MindScoreNetwork {
        try load(from: resourceBundle)
    }

    // MARK: Running

    public func run(_ z: [Double]) -> Run {
        /// Matches `Number(z[i]) || 0` followed by the clamp in net.js: a
        /// value that is not a number becomes zero, and an infinite one is
        /// clamped to the limit like any other large number.
        var a = (0..<architecture[0]).map { i -> Double in
            let raw = i < z.count ? z[i] : 0
            return clampZ(raw.isNaN ? 0 : raw)
        }
        let clamped = a
        var activations: [[Double]] = [a]
        for layer in layers {
            var next = [Double](repeating: 0, count: layer.cols)
            for j in 0..<layer.cols {
                var sum = layer.b[j]
                for i in 0..<layer.rows {
                    sum += a[i] * layer.w[i * layer.cols + j]
                }
                next[j] = layer.isLast ? Self.logistic(sum) : tanh(sum)
            }
            a = next
            activations.append(a)
        }
        let p = a[0]
        return Run(score: Int((p * 100).rounded()), p: p,
                   activations: activations, clampedInput: clamped)
    }

    public func score(_ z: [Double]) -> Int { run(z).score }

    /// Convenience for a keyed z vector.
    public func run(_ z: [Signal: Double]) -> Run {
        run(Self.inputOrder.map { z[$0] ?? 0 })
    }

    public func clampZ(_ x: Double) -> Double {
        min(max(x, -zLimit), zLimit)
    }

    /// The weight on one edge, for drawing.
    public func edge(layer: Int, from: Int, to: Int) -> Double {
        let l = layers[layer]
        return l.w[from * l.cols + to]
    }

    /// The largest absolute weight in a layer, so edge thickness can be
    /// relative to that layer rather than to the whole network, where the first
    /// layer would otherwise swamp the rest.
    public func edgeMax(layer: Int) -> Double {
        layers[layer].w.reduce(0) { max($0, abs($1)) }
    }

    static func logistic(_ x: Double) -> Double { 1 / (1 + exp(-x)) }

    // MARK: The reference model

    /// What the network was fitted against, so a screen can state the reference
    /// model beside the network's answer and the two can be checked against
    /// each other at runtime. `tools/net/train.py` is the authority for both.
    ///
    /// Every coefficient here is a starting allocation from published figures,
    /// not a value fitted to anybody. Signs carry direction: beat-to-beat
    /// variation falls under load, skin conductance rises, skin temperature
    /// falls. Movement is not a term, it is a gate.
    public enum Reference {
        public static let weights: [Double] = [1.3, 1.0, -0.8]
        public static let k: Double = 2.4
        public static let gateAt: Double = 1.2
        public static let gateSharpness: Double = 3.0

        public struct Result: Sendable {
            public let score: Int
            /// 1 when the wearer was still, falling toward 0 as the reading
            /// gets more active. What the gate multiplies the other three by.
            public let gate: Double
        }

        public static func run(_ z: [Double], zLimit: Double) -> Result {
            let c = (0..<4).map { i -> Double in
                let raw = i < z.count ? z[i] : 0
                return min(max(raw.isNaN ? 0 : raw, -zLimit), zLimit)
            }
            let gate = MindScoreNetwork.logistic(-gateSharpness * (c[3] - gateAt))
            let wSum = weights.reduce(0) { $0 + abs($1) }
            let s = gate * (weights[0] * c[0] + weights[1] * c[1] + weights[2] * c[2]) / wSum / 2
            return Result(score: Int((MindScoreNetwork.logistic(k * s) * 100).rounded()),
                          gate: gate)
        }
    }

    public func reference(_ z: [Double]) -> Reference.Result {
        Reference.run(z, zLimit: zLimit)
    }
}
